CREATE TABLE IF NOT EXISTS buzon_sunafil_casos (id_documento BIGINT NOT NULL PRIMARY KEY,id_cliente INT NOT NULL,id_responsable INT NULL,estado VARCHAR(20) NOT NULL DEFAULT 'ABIERTO',creado_por INT NOT NULL,modificado_por INT NOT NULL,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,cerrado_en DATETIME NULL,INDEX idx_casos_cliente(id_cliente),INDEX idx_casos_responsable(id_responsable)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS buzon_sunafil_avances (id_avance BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,id_documento BIGINT NOT NULL,id_cliente INT NOT NULL,id_usuario INT NOT NULL,contenido LONGTEXT NOT NULL,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_avances_documento(id_documento,creado_en),INDEX idx_avances_cliente(id_cliente)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
